import { useCallback, useEffect, useRef, useState } from 'react';
import type { Project, Task } from './task-tree.js';

const API = `${process.env.BACKEND_URL || ''}/trellis-service`;

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${API}${path}`, {
    credentials: 'include',
    headers: { 'Content-Type': 'application/json' },
    ...init,
  });
  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.message || `Request failed (${res.status})`);
  }
  return res.status === 204 ? (undefined as T) : res.json();
}

/**
 * Loads projects from the trellis service and exposes optimistic mutations.
 * Task-tree edits apply locally at once and are persisted with a short debounce.
 * @returns projects, loading/error state and mutation helpers
 */
export function useProjects() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const timers = useRef<Record<string, ReturnType<typeof setTimeout>>>({});

  useEffect(() => {
    request<Project[]>('/projects')
      .then(setProjects)
      .catch((e) => setError(e.message))
      .finally(() => setLoading(false));
  }, []);

  const createProject = useCallback(async (input: { name: string; description?: string; color?: string }) => {
    const created = await request<Project>('/projects', { method: 'POST', body: JSON.stringify({ ...input, tasks: [] }) });
    setProjects((p) => [...p, created]);
    return created;
  }, []);

  const deleteProject = useCallback(async (id: string) => {
    setProjects((p) => p.filter((x) => x.id !== id));
    await request(`/projects/${id}`, { method: 'DELETE' }).catch((e) => setError(e.message));
  }, []);

  const updateTasks = useCallback((id: string, fn: (tasks: Task[]) => Task[]) => {
    setProjects((list) =>
      list.map((p) => {
        if (p.id !== id) return p;
        const tasks = fn(p.tasks);
        clearTimeout(timers.current[id]);
        timers.current[id] = setTimeout(() => {
          request(`/projects/${id}`, { method: 'PUT', body: JSON.stringify({ tasks }) }).catch((e) => setError(e.message));
        }, 300);
        return { ...p, tasks };
      })
    );
  }, []);

  return { projects, loading, error, createProject, deleteProject, updateTasks, clearError: () => setError(null) };
}
